cd C:\invoice-work\2a068fa9\workspace; node --input-type=module -e " import fs from 'node:fs'; let s=fs.readFileSync('src/worker/pool.mjs','utf8'); const rep=(a,b)=>{ if(!s.includes(a)) throw new Error('missing '+a); s=s.replace(a,b); }; rep("import { fork } from 'node:child_process';", "import { fork } from 'node:child_process';
import { randomBytes } from 'node:crypto';"); rep('// WorkerPool: starts worker processes, replaces the ones that die, and returns
// jobs to the queue when their lease runs out.', '// WorkerPool: starts worker processes, replaces the ones that die, gives a dead
// worker's jobs back at once, and returns jobs to the queue when a lease runs out.'); rep('    this.incarnation = 0;', '    // Worker ids are unique to this pool, so that reclaiming one can never touch a
    // worker of another pool or of an earlier run that shares the queue directory.
    this.poolId = \`p\${process.pid}-\${randomBytes(3).toString("hex")}\`;
    this.incarnation = 0;
    this.unreclaimed = new Set();'); rep('  #reap() {
    try {
      this.queue.reapExpired();
    } catch (err) {
      this.emit("error-event", err);
    }
  }', 'X'); " 2>&1 | Select -First 5
